// Retired ids that people may still have saved, mapped to the avatar that replaced them.
const RENAMED: Record<string, string> = { "gold-cat": "gold-dragon" };

export const findAnimalAvatar = (id: string | null | undefined): AnimalAvatar | undefined =>
  id ? ANIMAL_AVATARS.find((avatar) => avatar.id === (RENAMED[id] ?? id)) : undefined;
